<section class="page-head"><div><p class="muted">Categorías globales o específicas por departamento para clasificar movimientos.</p></div><button class="btn btn-primary" id="newSubitemBtn">Nuevo sub-item</button></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Código</th><th>Sub-item</th><th>Departamento</th><th>Estatus</th><th></th></tr></thead><tbody id="subitemTable"></tbody></table></div></section>
<div class="modal hidden" id="subitemModal"><div class="modal-card"><div class="modal-head"><div><span class="eyebrow">CATÁLOGO</span><h2>Sub-item presupuestal</h2></div><button class="icon-btn" data-close-modal>✕</button></div><form id="subitemForm" class="form-grid"><input type="hidden" name="subitem_id"><label>Código<input name="codigo" required></label><label>Nombre<input name="nombre" required></label><label class="full">Departamento<select name="departamento_id" id="subitemDepartment"><option value="">Global / Todos</option></select></label><label class="full">Descripción<textarea name="descripcion" rows="3"></textarea></label><label>Estatus<select name="estatus"><option>ACTIVO</option><option>INACTIVO</option></select></label><div class="form-actions full"><button type="button" class="btn btn-ghost" data-close-modal>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form></div></div>
